-- ── khld_milestone_verification (SO1-A1, SO1-B1, SO3-E1, SO3-F1) ──

create table public.khld_milestone_verification (
  id                    uuid primary key default gen_random_uuid(),
  municipality_id       uuid not null references public.municipality(id) default public.my_municipality(),
  milestone_code        text not null check (milestone_code in ('SO1-A1', 'SO1-B1', 'SO3-E1', 'SO3-F1')),
  verif_date            date not null,
  verif_round_id        uuid references public.ref_khld_a1_verif_round(id),
  verif_by              text not null,
  period_covered_from   date,
  period_covered_to     date,
  coordinator_decision_no text,
  coordinator_decision_date date,
  coordinator_officer_name text,
  stakeholder_updated   date,
  tracking_format_id    uuid references public.ref_khld_a1_tracking_format(id),
  intro_meetings        int,
  council_decision_id   uuid references public.ref_khld_a1_council_decision(id),
  council_decision_other text,
  gaps                  text not null,
  countersign_name      text,
  countersign_date      date,
  protocol_ref          text,
  calendar_horizon_id   uuid references public.ref_khld_b1_calendar_horizon(id),
  requests_received     int,
  requests_approved     int,
  requests_declined     int,
  last_updated          date,
  founding_meeting_date date,
  founding_meeting_venue text,
  invited_count         int,
  attended_count        int,
  orgs_joined           text,
  orgs_withdrew         text,
  meeting_cycle_id      uuid references public.ref_khld_e1_meeting_cycle(id),
  meetings_held         int,
  meetings_with_minutes int,
  duplication_avoided_id uuid references public.ref_khld_e1_duplication_avoided(id),
  duplication_avoided_other text,
  committee_coordinator_name text,
  community_coordinator_name text,
  signed_on             date,
  launch_date           date,
  database_format_id    uuid references public.ref_khld_f1_database_format(id),
  registered_count      int,
  registered_women      int,
  registered_youth      int,
  registered_refugees   int,
  registered_pwd        int,
  recognition_delivered int,
  focal_point_id        uuid references public.ref_khld_f1_focal_point(id),
  focal_point_other     text,
  action_days_since_launch int,
  client_uuid           uuid unique,
  created_at            timestamptz not null default now(),
  updated_at            timestamptz not null default now(),
  created_by            uuid references auth.users(id) default auth.uid(),
  deleted_at            timestamptz,
  constraint khld_milestone_verification_id_municipality_key unique (id, municipality_id),
  constraint khld_milestone_verification_so1_a1_columns check (milestone_code <> 'SO1-A1' or (protocol_ref is null and calendar_horizon_id is null and requests_received is null and requests_approved is null and requests_declined is null and last_updated is null and founding_meeting_date is null and founding_meeting_venue is null and invited_count is null and attended_count is null and orgs_joined is null and orgs_withdrew is null and meeting_cycle_id is null and meetings_held is null and meetings_with_minutes is null and duplication_avoided_id is null and duplication_avoided_other is null and committee_coordinator_name is null and community_coordinator_name is null and signed_on is null and launch_date is null and database_format_id is null and registered_count is null and registered_women is null and registered_youth is null and registered_refugees is null and registered_pwd is null and recognition_delivered is null and focal_point_id is null and focal_point_other is null and action_days_since_launch is null)),
  constraint khld_milestone_verification_so1_b1_columns check (milestone_code <> 'SO1-B1' or (verif_round_id is null and period_covered_from is null and period_covered_to is null and coordinator_decision_no is null and coordinator_decision_date is null and coordinator_officer_name is null and stakeholder_updated is null and tracking_format_id is null and intro_meetings is null and council_decision_id is null and council_decision_other is null and founding_meeting_date is null and founding_meeting_venue is null and invited_count is null and attended_count is null and orgs_joined is null and orgs_withdrew is null and meeting_cycle_id is null and meetings_held is null and meetings_with_minutes is null and duplication_avoided_id is null and duplication_avoided_other is null and committee_coordinator_name is null and community_coordinator_name is null and signed_on is null and launch_date is null and database_format_id is null and registered_count is null and registered_women is null and registered_youth is null and registered_refugees is null and registered_pwd is null and recognition_delivered is null and focal_point_id is null and focal_point_other is null and action_days_since_launch is null)),
  constraint khld_milestone_verification_so3_e1_columns check (milestone_code <> 'SO3-E1' or (verif_round_id is null and period_covered_from is null and period_covered_to is null and coordinator_decision_no is null and coordinator_decision_date is null and coordinator_officer_name is null and stakeholder_updated is null and tracking_format_id is null and intro_meetings is null and council_decision_id is null and council_decision_other is null and countersign_name is null and countersign_date is null and protocol_ref is null and calendar_horizon_id is null and requests_received is null and requests_approved is null and requests_declined is null and last_updated is null and launch_date is null and database_format_id is null and registered_count is null and registered_women is null and registered_youth is null and registered_refugees is null and registered_pwd is null and recognition_delivered is null and focal_point_id is null and focal_point_other is null and action_days_since_launch is null)),
  constraint khld_milestone_verification_so3_f1_columns check (milestone_code <> 'SO3-F1' or (verif_round_id is null and period_covered_from is null and period_covered_to is null and coordinator_decision_no is null and coordinator_decision_date is null and coordinator_officer_name is null and stakeholder_updated is null and tracking_format_id is null and intro_meetings is null and council_decision_id is null and council_decision_other is null and countersign_name is null and countersign_date is null and protocol_ref is null and calendar_horizon_id is null and requests_received is null and requests_approved is null and requests_declined is null and last_updated is null and founding_meeting_date is null and founding_meeting_venue is null and invited_count is null and attended_count is null and orgs_joined is null and orgs_withdrew is null and meeting_cycle_id is null and meetings_held is null and meetings_with_minutes is null and duplication_avoided_id is null and duplication_avoided_other is null and committee_coordinator_name is null and community_coordinator_name is null and signed_on is null))
);
