create index khld_milestone_verification_created_by_idx on public.khld_milestone_verification (created_by);
create index khld_milestone_verification_verif_round_id_idx on public.khld_milestone_verification (verif_round_id);
create index khld_milestone_verification_tracking_format_id_idx on public.khld_milestone_verification (tracking_format_id);
create index khld_milestone_verification_council_decision_id_idx on public.khld_milestone_verification (council_decision_id);
create index khld_milestone_verification_calendar_horizon_id_idx on public.khld_milestone_verification (calendar_horizon_id);
